local FishingUtils = import('Game.UI.Fishing.FishingUtils')
local ResourceModule = CS.Engine.Modules.ResourceModule
local ConstantsFishing = import('Game.UI.Fishing.ConstantsFishing')
local KTool = CS.Engine.Lib.KTool
local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds
local UIRaycastBlocker = CS.Engine.UI.UIRaycastBlocker.Instance

---------------------------------------------------------------

---@class FishActivityService
local FishActivityService = Class("FishActivityService")

function FishActivityService.new(luaDialog)
    local instance = FishActivityService.New()
    instance.luaDialog = luaDialog

    for k, v in pairs(luaDialog) do
        instance[k] = v
    end

    return instance
end

function FishActivityService:OnShow()
    cs_coroutine.start(function()
        UIRaycastBlocker:AddCondition("UIFishPoolGoFishingShowNode2")
        coroutine.yield(WaitForSeconds(0.5))
        local isActivity = FishingUtils.IsFishPlaceActivitying(self.placeId)
        if isActivity then
            local vo = FishingUtils.GetFishActivityPlanVo(self._activityId)
            local luaPath = ""
            if checkNumber(vo.activity) == ConstantsFishing.ActivityType.KingChallenge then
                luaPath = "Game.UI.Fishing.UIFishPoolGoFishingDialog.UIFishPoolGoFishingNode2"
            end

            local scr = CfUtils.GetLuaScr(self._activityGo, luaPath)
            if scr then
                scr:OnShow()
            end
        end
        UIRaycastBlocker:RemoveCondition("UIFishPoolGoFishingShowNode2")
    end)
end

function FishActivityService:UpdateInfo()
    local isActivity = FishingUtils.IsFishPlaceActivitying(self.placeId)
    if not isActivity then
        return
    end

    local data = FishingUtils.GetFishPlaceDojoActivityData(self.placeId)
    if not data then
        return
    end

    self._activityId = checkNumber(data.contentId)
    local vo = FishingUtils.GetFishActivityPlanVo(self._activityId)
    if not vo then
        return
    end

    self._activityLoader = ResourceModule.LoadBundleSync("Prefabs/FishPool/FishPoolActivityMainNode"..vo.changeId..".prefab", nil, true)
    if self._activityLoader and self._activityLoader.IsSuccess then
        self._activityGo = CS.UnityEngine.GameObject.Instantiate(self._activityLoader.ResultObject)
        KTool.SetParent(self._activityGo, self.controller.gameObject.transform:Find("Container").gameObject, false)

        KTool.SetActive(self._activityGo, true)
    else
        self._activityLoader:Release()
    end

    if isNull(self._activityGo) then
        return
    end

    local luaPath = ""
    if checkNumber(vo.activity) == ConstantsFishing.ActivityType.Summer then
        luaPath = "Game.UI.Fishing.UIFishPoolGoFishingDialog.UIFishPoolGoFishingNode1"
    elseif checkNumber(vo.activity) == ConstantsFishing.ActivityType.KingChallenge then
        luaPath = "Game.UI.Fishing.UIFishPoolGoFishingDialog.UIFishPoolGoFishingNode2"
    end

    local scr = CfUtils.GetLuaScr(self._activityGo, luaPath)
    if scr then
        scr:Refresh(self.placeId, self)
    end
end

function FishActivityService:ShowMe()
    local isActivity = FishingUtils.IsFishPlaceActivitying(self.placeId)
    if isActivity then
        CfUtils.SetActive(self._activityGo, true)
    end
end

function FishActivityService:HideMe()
    if isNotNull(self._activityGo) then
        KTool.SetActive(self._activityGo, false)
    end
end

function FishActivityService:CheckActivity()
    --进来的时候是否有活动
    if checkNumber(self._activityId) > 0 then
        --判断是否开启中
        local isOpen = FishingUtils.IsActivityOpen(self.placeId)
        if not isOpen then
            GameUtils.Toast(localize("活动已结束"))
            return
        end
    end
end

function FishActivityService:Release()
    if not isNull(self._activityLoader) then
        self._activityLoader:Release()
    end
end

return FishActivityService